class NotificationPane extends StatelessWidget{const NotificationPane({super.key,required this.api,required this.data,required this.onSaved});final IranHubApi api;final Map<String,dynamic> data;final Future<void> Function() onSaved;Future<void> set(String key,bool value)async{await api.call('PATCH','/v1/me/notification-preferences',body:{key:value});await onSaved();}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[SwitchListTile(title:const Text('بنر داخل برنامه'),value:data['in_app_banner']==true,onChanged:(v)=>set('inAppBanner',v)),SwitchListTile(title:const Text('یادآوری برنامه'),value:data['planner_reminders']!=false,onChanged:(v)=>set('plannerReminders',v)),SwitchListTile(title:const Text('یادآوری مدرسه'),value:data['school_reminders']!=false,onChanged:(v)=>set('schoolReminders',v)),SwitchListTile(title:const Text('یادآوری تقویم'),value:data['calendar_reminders']!=false,onChanged:(v)=>set('calendarReminders',v)),SwitchListTile(title:const Text('نمایش متن حساس روی اعلان'),subtitle:const Text('به‌صورت پیش‌فرض خاموش است.'),value:data['sensitive_preview']==true,onChanged:(v)=>set('sensitivePreview',v))]);}
class CyclePane extends StatelessWidget{const CyclePane({super.key,required this.api,required this.data,required this.onSaved});final IranHubApi api;final Map<String,dynamic> data;final Future<void> Function() onSaved;Future<void> add()async{final now=DateTime.now();await api.call('POST','/v1/me/menstrual-cycles',body:{'startsOn':'${now.year}-${now.month.toString().padLeft(2,'0')}-${now.day.toString().padLeft(2,'0')}','reminderEnabled':false});await onSaved();}@override Widget build(BuildContext context){final rows=data['entries'] as List<dynamic>???const[];return ListView(padding:const EdgeInsets.all(16),children:[const Text('چرخه شخصی',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const Text('کاملاً خصوصی برای صاحب حساب؛ ابزار ثبت و یادآوری است و کاربرد تشخیصی ندارد.'),const SizedBox(height:12),FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('ثبت شروع امروز')),...rows.map((r){final m=Map<String,dynamic>.from(r as Map);return Card(child:ListTile(title:Text('شروع: ${m['starts_on']}'),subtitle:Text(m['notes']?.toString()??'')));})]);}}
